Use this C# code example as a reference for your client application:
            
             public static void ImportDeviceQuery(string zipFileFullPath)
             {
               // Create the query request with RestSharp API client library.
               // (see https://restsharp.dev/).
            
               var request = new RestRequest("import/device_type_query", Method.POST);
            
               // Add file content for upload.
               request.AddFileBytes("file", File.ReadAllBytes(zipFileFullPath),
                                    Path.GetFileName(zipFileFullPath), "application/octet-stream");
            
               // Add authentication.
               request.AddHeader("Authorization", "Bearer XXXXXXXXXXXXXXX...");
            
               // Execute the request. You need to use a real SSL-protected url.
               var response = new RestClient("http://localhost/NetTerrain/wapi/v1").Execute(request);
            
               if (response.ResponseStatus == ResponseStatus.Completed)
               {
                 // Output the import log returned as a plain text with the successful response.
                 Console.Write(response.Content.ToString().Replace(@"\r\n", Environment.NewLine));
               }
               else
               {
                 // Process error.
               }
             }

